export const getAuthSignInUrl = () => {
  return `/api/v1/auth/signin`;
};

/**
 * Authenticate email/password and establish one new independent AuthSession.
 * @summary Sign In
 */
export const authSignIn = async (
  signInRequest: SignInRequest,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<authSignInResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  const res = await (fetchFn ?? fetch)(getAuthSignInUrl(), {
    ...options,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(signInRequest),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: authSignInResponse['data'] = body ? JSON.parse(body) : {};
  return {
    data,
    status: res.status,
    headers: res.headers,
  } as authSignInResponse;
};

